import React from 'react';
import { connect } from 'react-redux';
import {
  Collapse,
  Navbar,
  NavbarToggler,
  // NavbarBrand,
  Nav,
  Dropdown,
  DropdownToggle,
  DropdownMenu,
  DropdownItem,
  Container,
} from 'reactstrap';

import dashboardRoutes from 'routes/AdminRoutes.jsx';
import { logout } from 'actions/admin/auth';
import { store } from '../../index';
import {
  // getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
  getLoggedUserUtils,
  setGlobalSchoolUtils,
} from '../../utils/commonFunc';
import AccountCircleIcon from '@material-ui/icons/AccountCircle';
import CommonTooltip from 'views/admin/Common/CommonTooltip';
import BatchSwitch from 'views/admin/Common/BatchSwitch';
import CustomButton from 'components/CustomButton';
import constants from 'config/constants';
import ExitToAppIcon from '@material-ui/icons/ExitToApp';
// eslint-disable-next-line no-unused-vars -- kept for the commented-out "App Settings" menu item below
import SettingsApplicationsIcon from '@material-ui/icons/SettingsApplications';

const roleLabels = {
  [constants.roles.SA]: 'Super admin',
  [constants.roles.admin]: 'Admin',
  [constants.roles.teacher]: 'Teacher',
  [constants.roles.guardian]: 'Guardian',
};

let timer;
class Header extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      isOpen: false,
      dropdownOpen: false,
      color: 'transparent',
      loggedUser: {},
      schoolDropdownOpen: false,
    };
    this.toggle = this.toggle.bind(this);
    this.dropdownToggle = this.dropdownToggle.bind(this);
    this.sidebarToggle = React.createRef();
  }

  toggle() {
    if (this.state.isOpen) {
      this.setState({
        color: 'transparent',
      });
    } else {
      this.setState({
        color: 'dark',
      });
    }
    this.setState({
      isOpen: !this.state.isOpen,
    });
  }

  dropdownToggle() {
    this.setState({
      dropdownOpen: !this.state.dropdownOpen,
    });
  }

  getBrand() {
    let name;
    dashboardRoutes.map(prop => {
      if (prop.collapse) {
        prop.views.map(subProp => {
          if (subProp.path === this.props.location.pathname) {
            name = subProp.name;
          }
          return null;
        });
      } else if (prop.path === this.props.location.pathname) {
        name = prop.name;
      }
      return null;
    });

    return name;
  }

  openSidebar() {
    document.documentElement.classList.toggle('nav-open');
    this.sidebarToggle.current.classList.toggle('toggled');
  }

  // function that adds color dark/transparent to the navbar on resize (this is for the collapse)
  updateColor() {
    // On a wide screen the sidebar is always shown, so an open phone-style menu (and the cross on its button) is reset.
    if (window.innerWidth >= 993 && document.documentElement.classList.contains('nav-open')) {
      document.documentElement.classList.remove('nav-open');
      this.sidebarToggle.current?.classList.remove('toggled');
    }
    if (window.innerWidth < 993 && this.state.isOpen) {
      this.setState({
        color: 'dark',
      });
    } else {
      this.setState({
        color: 'transparent',
      });
    }
  }

  componentDidMount() {
    window.addEventListener('resize', this.updateColor.bind(this));
    this.setState({ loggedUser: getLoggedUserUtils() });
    // Initial Update global school
    const globalSchool = getGlobalSchoolUtils();
    const { schools, school } = this.props;
    if (!globalSchool) {
      if (schools && schools.length) {
        this.updateSchoolState(schools[0]);
      } else if (school && Object.keys(school).length) {
        this.updateSchoolState(school);
      }
    } else {
      this.updateSchoolState(globalSchool);
    }
  }

  componentDidUpdate(e) {
    if (
      window.innerWidth < 993 &&
      e.history.location.pathname !== e.location.pathname &&
      document.documentElement.className.indexOf('nav-open') !== -1
    ) {
      document.documentElement.classList.toggle('nav-open');
      this.sidebarToggle.current.classList.toggle('toggled');
    }
    // Update global school
    const globalSchool = getGlobalSchoolUtils();
    const { schools, school } = this.props;
    if (!globalSchool) {
      if (schools && schools.length && e.schools !== schools) {
        this.updateSchoolState(schools[0]);
      } else if (school && e.school !== school && Object.keys(school).length) {
        this.updateSchoolState(school);
      }
    } else if ((schools && e.schools !== schools) || (school && e.school !== school)) {
      this.updateSchoolState(globalSchool);
    }
  }

  updateSchoolState = school => {
    const globalSchool = getGlobalSchoolUtils();
    if (!globalSchool || globalSchool?.schoolId !== school?.schoolId) {
      store.dispatch({ type: 'CLEAR_STORE_EXCEPT_AUTH_SCHOOL' });
      const gSchool = {
        schoolId: school.schoolId,
        schoolCode: school.schoolCode,
        language: school.language,
        schoolName: school.schoolName,
      };
      setGlobalSchoolUtils(gSchool);
      this.setState({ selectedSchool: school.schoolName });
      timer = setTimeout(() => {
        if (this.props.location.pathname !== '/admin/dashboard') {
          this.props.navigateToHome();
        }
      }, 300);
    } else if (globalSchool) {
      this.setState({ selectedSchool: globalSchool.schoolName });
    }
  };

  logout = () => {
    this.props.logout();
    store.dispatch({ type: 'CLEAR_STORE' });
    this.props.history.push('/admin/login');
  };

  schoolDropdownToggle = () => {
    this.setState(prevState => ({
      schoolDropdownOpen: !prevState.schoolDropdownOpen,
    }));
  };

  componentWillUnmount() {
    if (timer) {
      clearTimeout(timer);
    }
  }

  render() {
    const {
      loggedUserRole,
      // schools,
      // currentBatch,
      location: { pathname },
    } = this.props;
    const {
      loggedUser,
      dropdownOpen,
      // schoolDropdownOpen, selectedSchool
    } = this.state;
    // add or remove classes depending if we are on full-screen-maps page or not
    // const batchData = getGlobalCurrentBatchUtils() || currentBatch;
    return (
      <Navbar
        color={pathname.indexOf('full-screen-maps') !== -1 ? 'light' : this.state.color}
        expand="lg"
        className={
          pathname.indexOf('full-screen-maps') !== -1
            ? 'navbar-absolut fixed-top'
            : `navbar-absolute fixed-top ${this.state.color === 'transparent' ? 'navbar-transparent ' : ''} bg-white`
        }
        style={{
          zIndex: 1,
          position: 'sticky',
          height: 59,
          boxSizing: 'border-box',
          borderBottom: '1px solid #EADCF7',
        }}>
        <Container fluid>
          <div className="navbar-wrapper">
            <div className="navbar-toggle">
              <button
                type="button"
                ref={this.sidebarToggle}
                className="navbar-toggler"
                onClick={() => this.openSidebar()}>
                <span className="navbar-toggler-bar bar1" />
                <span className="navbar-toggler-bar bar2" />
                <span className="navbar-toggler-bar bar3" />
              </button>
            </div>
            {/* <NavbarBrand style={{ fontSize: 16 }}>
              <strong>{this.getBrand()}</strong>
            </NavbarBrand> */}
            {loggedUserRole !== constants.roles.teacher && (
              // BatchSwitch is a Bootstrap row (-15px side margins), so it needs the padding back or it slides under the
              // menu button on a small screen.
              <div style={{ paddingLeft: 22, paddingRight: 15, minWidth: 0 }}>
                <BatchSwitch
                  navToCloneBatch={this.props.navToCloneBatch}
                  hideClone={pathname.includes('/admin/clone-batch')}
                />
              </div>
            )}
          </div>
          <NavbarToggler onClick={this.toggle}>
            <span className="navbar-toggler-bar navbar-kebab" />
            <span className="navbar-toggler-bar navbar-kebab" />
            <span className="navbar-toggler-bar navbar-kebab" />
          </NavbarToggler>
          <Collapse isOpen={this.state.isOpen} navbar className="justify-content-end">
            <Nav navbar className="align-items-center">
              {constants.API_BASE_URL.includes('localhost') && (
                <CustomButton
                  name="Local Server Connected"
                  variant="outlined"
                  color="default"
                  size="small"
                  className="local-server-badge"
                  style={{
                    fontSize: 11,
                    padding: '4px 10px',
                    minHeight: 0,
                    lineHeight: '18px',
                    borderRadius: 4,
                    marginRight: 16,
                    cursor: 'default',
                  }}
                />
              )}
              {/* School list Dropdown */}
              {/* <Dropdown nav isOpen={schoolDropdownOpen} toggle={e => this.schoolDropdownToggle(e)}>
                <DropdownToggle
                  caret={schools?.length > 1}
                  nav
                  onClick={() => {
                    if (!pathname.includes('/admin/dashboard') && loggedUserRole !== constants.roles.SA) {
                      this.props.history.push('/admin/dashboard');
                    }
                  }}>
                  {selectedSchool ? (
                    <i className="fas fa-school" style={{ fontSize: 16, top: -2, marginRight: 12 }} />
                  ) : null}
                  <span style={{ fontSize: 16 }}>
                    {selectedSchool}{' '}
                    <span style={{ color: 'green' }}>
                      {batchData?.startYear ? `[${batchData.startYear} - ${batchData.endYear}]` : null}
                    </span>
                  </span>
                </DropdownToggle>
                {loggedUserRole === constants.roles.SA && schools?.length > 1 ? (
                  <DropdownMenu right>
                    {schools?.map(item => {
                      return (
                        <DropdownItem
                          key={item.schoolId}
                          tag="a"
                          onClick={() => {
                            this.updateSchoolState(item);
                          }}>
                          {item.schoolName}
                        </DropdownItem>
                      );
                    })}
                  </DropdownMenu>
                ) : null}
              </Dropdown> */}

              {/* User Dropdown */}
              <Dropdown nav isOpen={dropdownOpen} toggle={e => this.dropdownToggle(e)}>
                <DropdownToggle nav>
                  {/* <i className="fas fa-user" style={{ fontSize: 16, top: -1 }} /> */}
                  <CommonTooltip content={loggedUser.fullName}>
                    <AccountCircleIcon fontSize="large" />
                  </CommonTooltip>
                  {/* <span style={{ fontSize: 16 }}>{loggedUser.fullName}</span> */}
                </DropdownToggle>
                <DropdownMenu right style={{ cursor: 'pointer' }}>
                  {loggedUser?.fullName && (
                    <>
                      <div style={{ padding: '6px 24px 8px', maxWidth: 260, cursor: 'default' }}>
                        <div
                          style={{
                            fontSize: 14,
                            fontWeight: 'bold',
                            color: '#1f2933',
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            whiteSpace: 'nowrap',
                          }}>
                          {loggedUser.fullName}
                        </div>
                        {roleLabels[loggedUser.userRole] && (
                          <div style={{ fontSize: 12, color: '#6b778a' }}>{roleLabels[loggedUser.userRole]}</div>
                        )}
                      </div>
                      <DropdownItem divider />
                    </>
                  )}
                  <DropdownItem
                    tag="a"
                    style={{ color: '#000000', fontSize: 13 }}
                    onClick={() => {
                      if (!pathname.includes('my-profile')) {
                        this.props.history.push('/admin/my-profile');
                      }
                    }}>
                    <AccountCircleIcon fontSize="small" className="mr-2" style={{ marginBottom: 2 }} />
                    My Profile
                  </DropdownItem>
                  {/* Hidden per request - keeping the code in case it needs to come back.
                  <DropdownItem
                    tag="a"
                    style={{ color: '#000000', fontSize: 13 }}
                    onClick={() => {
                      if (!pathname.includes('app-settings')) {
                        this.props.history.push('/admin/app-settings');
                      }
                    }}>
                    <SettingsApplicationsIcon fontSize="small" className="mr-2" style={{ marginBottom: 2 }} />
                    App Settings
                  </DropdownItem>
                  */}
                  <DropdownItem tag="a" onClick={this.logout} style={{ color: '#000000', fontSize: 13 }}>
                    <ExitToAppIcon fontSize="small" className="mr-2" style={{ marginBottom: 2 }} />
                    Logout
                  </DropdownItem>
                </DropdownMenu>
              </Dropdown>
            </Nav>
          </Collapse>
        </Container>
      </Navbar>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserRole: state.auth.loggedUserRole,
    currentBatch: state.batches.currentBatch,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    logout: () => dispatch(logout()),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(Header);
