import React, { useEffect, useState } from 'react';
import { Row } from 'reactstrap';
import { IconButton } from '@material-ui/core';
import { FileCopyRounded } from '@material-ui/icons';
import CommonTooltip from './CommonTooltip';
import {
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
  getCurrentYearBatchUtils,
  setGlobalCurrentBatchUtils,
  isActualCurrentBatchOrHigher,
} from 'utils/commonFunc';
import { useDispatch, useSelector } from 'react-redux';
import { useHistory } from 'react-router-dom';
import { fetchSchoolBatchsService } from 'actions/admin/batches';
import Select from '@material-ui/core/Select';
import MenuItem from '@material-ui/core/MenuItem';
import ConfirmModal from './ConfirmModal';
import Brightness1Icon from '@material-ui/icons/Brightness1';
