const initialConfirmData = {
  confirmModalOpen: false,
  confirmMessage: '',
  confirmedBatch: {},
};

function BatchSwitch({ hideClone }) {
  // const classes = useStyles();
  const history = useHistory();
  const dispatch = useDispatch();
  const globalSchool = getGlobalSchoolUtils();
  const { startYear: currentStartYear } = getCurrentYearBatchUtils();
  const { startYear, batchId } = getGlobalCurrentBatchUtils();
  const { batchId: actualCurrentBatchId } = getGlobalCurrentBatchUtils('actualCurrentBatch');
  const reduxStore = useSelector(state => state);
  const {
    auth: { loggedUserToken, loggedUserSchool },
    batches: { batchList },
  } = reduxStore;
  const [batch, setBatch] = useState({});
  const [batchSwitchConfirmData, setConfirmData] = useState(initialConfirmData);

  const updateBatch = () => {
    if (!batchList?.length) {
      if (globalSchool?.schoolId) {
        dispatch(
          fetchSchoolBatchsService({
            schoolId: globalSchool?.schoolId || loggedUserSchool,
            token: loggedUserToken,
          })
        );
      }
    } else {
      const itemIndex = batchList?.findIndex(el => el?.batchId === batchId || el?.startYear === startYear);
      if (!batch?.batchId && itemIndex !== null && itemIndex > -1) {
        const batchItem = batchList?.[itemIndex];
        setBatch({ ...batchItem, isActive: true, itemIndex });
      }
    }
  };

  useEffect(() => {
    updateBatch();
  }, [batchList?.length, globalSchool?.schoolId]);

  const confirmNo = () => {
    setConfirmData(initialConfirmData);
  };

  const confirmYes = () => {
    const bData = {
      batchId: batchSwitchConfirmData?.confirmedBatch?.batchId,
      startYear: batchSwitchConfirmData?.confirmedBatch?.startYear,
      endYear: batchSwitchConfirmData?.confirmedBatch?.endYear,
    };
    setGlobalCurrentBatchUtils(bData);
    setBatch(batchSwitchConfirmData?.confirmedBatch);
    confirmNo();
    dispatch({ type: 'CLEAR_STORE_EXCEPT_AUTH_SCHOOL' });
    history.push(`/admin/dashboard`);
  };

  const findAndUpdateStateBatch = passBatchId => {
    const batchItem = passBatchId && batchList?.find(el => el?.batchId === passBatchId);
    if (batchItem) {
      setConfirmData(prevState => ({
        ...prevState,
        confirmModalOpen: true,
        confirmMessage: `Changing batch will reset your app to batch ${batchItem?.startYear} - ${batchItem?.endYear}. Are you sure you want to proceed?`,
        confirmedBatch: batchItem,
      }));
    } else {
      confirmNo();
    }
  };

  const handleChange = event => {
    findAndUpdateStateBatch(event.target.value);
  };

  return batch?.batchId ? (
    <>
      <Row className="align-items-center">
        <Select
          labelId="demo-simple-select-label"
          id="demo-simple-select"
          value={batchList?.length ? batch?.batchId : ''}
          onChange={handleChange}
          IconComponent={() => null}
          //className={classes.select}
        >
          {batchList?.map(el => {
            return (
              <MenuItem key={el?.batchId} value={el?.batchId}>
                <CommonTooltip
                  style={{ fontSize: 17 }}
                  placement="right"
                  content={el?.batchId === actualCurrentBatchId ? 'Current batch' : 'Exist batch'}>
                  {el?.batchId === actualCurrentBatchId ? (
                    <Brightness1Icon style={{ fontSize: 16, color: 'green', margin: '-3px 5px 0px 0px' }} />
                  ) : (
                    <Brightness1Icon style={{ fontSize: 16, color: 'orange', margin: '-3px 5px 0px 0px' }} />
                  )}
                  <span className="ml-1">{el?.name}</span>
                </CommonTooltip>
              </MenuItem>
            );
          })}
        </Select>
        {batchList?.length > 0 &&
          (batch?.startYear <= currentStartYear || isActualCurrentBatchOrHigher()) &&
          !hideClone && (
            <span style={{ marginLeft: 0 }}>
              <CommonTooltip content={`Clone batch ${batch?.startYear} - ${batch.endYear}`} placement="right">
                <IconButton onClick={() => history.push(`/admin/clone-batch?clonefrom=${batch?.startYear}`)}>
                  <FileCopyRounded fontSize="small" />
                </IconButton>
              </CommonTooltip>
            </span>
          )}
      </Row>
      <ConfirmModal
        headerStyle={{ fontSize: 18 }}
        size="md"
        confirmModalOpen={batchSwitchConfirmData?.confirmModalOpen}
        deleteConfirm={confirmYes}
        deleteCancel={confirmNo}
        confirmMessage={batchSwitchConfirmData?.confirmMessage}
      />
    </>
  ) : null;
}

export default BatchSwitch;
